/* Second-batch tools stay in the existing owner dashboard and scoped admin preview. */
(()=>{'use strict';
let tab='levels',data=null,key='',busy=false,error='',dirty=false,search='',page=0,saving=false,discardResolve=null;
const tabs=[['levels','مستويات الولاء'],['offers','عروض أوقات الهدوء'],['reminders','التذكيرات']],names={inactive:'عميل منقطع',near:'قريب من المكافأة',ready:'مكافأة جاهزة'},days=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
navOwner.push(['engagement','star','تطوير الولاء']);
const args=()=>({shop:db.shop,...(db.scopedBusiness?{scope:db.scopedBusiness}:{})});
const identity=()=>[principal?.kind,principal?.account,db.shop,db.scopedBusiness].join(':');
function field(label,content){return `<label class="field"><span>${label}</span>${content}</label>`;}
function input(name,value,type='text',extra=''){return `<input class="input" name="${name}" type="${type}" value="${esc(value??'')}" ${extra}>`;}
function check(name,label,value,extra=''){return `<label class="eng-check"><input type="checkbox" name="${name}" ${value?'checked':''} ${extra}> ${label}</label>`;}
function select(name,values,current){return `<select class="input" name="${name}">${values.map(([v,n])=>`<option value="${v}" ${String(v)===String(current)?'selected':''}>${n}</option>`).join('')}</select>`;}
function actions(){return '<div class="eng-actions"><span class="eng-save-state" role="status"></span><button class="btn primary" type="submit">حفظ الإعدادات</button></div>';}
async function refresh(force=false){if(!serverMode||publicPage||role!=='owner'||view!=='engagement'||busy)return;const next=identity();if(!force&&key===next)return;key=next;busy=true;error='';
 try{const result=await api('/api/engagement/report?'+new URLSearchParams(args()));if(identity()===next){data=result;dirty=false;page=0;}}
 catch(e){if(identity()===next){error=e.message;data=null;}}
 finally{busy=false;if(role==='owner'&&view==='engagement')render();}
}
function levelRow(t,i){const points=Loyalty.program(shop().card).type==='points';return `<fieldset class="eng-tier" data-tier><legend>المستوى ${fmt(i+1)}</legend><div class="eng-grid">${field('اسم المستوى',input('name',t.name,'text','required maxlength="24"'))}${field('حد الوصول',input('threshold',t.threshold,'number','required min="1" max="10000000" step="1"'))}${points?field('النقاط لكل زيارة',select('multiplier',[[1,'النقاط المعتادة'],[2,'ضعف النقاط'],[3,'ثلاثة أضعاف']],t.multiplier)):input('multiplier',1,'hidden')}${field('ميزة توضحها للعميل · اختياري',input('benefit',t.benefit,'text','maxlength="120" placeholder="مثل: أولوية الحجز"'))}</div><button class="btn secondary small" type="button" data-eng-remove="tier">حذف المستوى</button></fieldset>`;}
function levels(){const c=data.settings.levels,rows=data.rows.filter(r=>(r.name+' '+r.phone).includes(search)),shown=rows.slice(page*15,page*15+15);return `<div class="eng-layout"><section class="panel growth-panel"><h2>كافئ استمرار العميل</h2><p class="sub">المستوى يحتسب تلقائيًا حسب القاعدة التي تختارها. تغيير الإعدادات يعيد تقييم المستوى، دون تعديل رصيد العميل.</p><form id="eng-levels">${check('enabled','تفعيل مستويات هذه البطاقة',c.enabled)}<div class="eng-grid">${field('طريقة الاحتساب',select('metric',[['visits','عدد الزيارات'],['spend','المبالغ المسجلة']],c.metric))}${field('الفترة',select('window',[[0,'من بداية العضوية'],[90,'آخر 90 يومًا'],[365,'آخر 365 يومًا']],c.window))}</div><p class="eng-note">المبالغ تحتسب من العمليات التي أدخل الموظف مبلغها فقط. العمليات المتراجع عنها مستبعدة. المستوى قد ينخفض عند استخدام فترة متحركة.</p><div id="eng-tiers">${c.tiers.map(levelRow).join('')}</div><button type="button" class="btn secondary small" data-eng-add="tier">إضافة مستوى</button><p class="eng-note">مضاعفة النقاط تطبق على الزيارات القادمة حسب المستوى قبل الزيارة. المزايا المكتوبة مثل أولوية الحجز ينفذها نشاطك. يظهر المستوى في صفحة العميل وتفاصيل Wallet، دون تغيير تصميم البطاقة.</p>${actions()}</form></section><section class="panel growth-panel"><h2>توزيع العملاء</h2><div class="eng-counts">${[{id:'base',name:'عضو'},...c.tiers].map(t=>`<div><strong>${fmt(data.counts[t.id]||0)}</strong><span>${esc(t.name)}</span></div>`).join('')}</div>${!c.enabled?'<p class="eng-note">المستويات متوقفة حاليًا. فعّلها بعد مراجعة الحدود والمزايا.</p>':''}<label class="field"><span>البحث عن عميل</span><input class="input" data-eng-search value="${esc(search)}" placeholder="اسم أو جوال" type="search"></label><div class="eng-table"><table><thead><tr><th>العميل</th><th>المستوى</th><th>التقدم</th></tr></thead><tbody>${shown.map(r=>`<tr><td>${esc(r.name)}<small dir="ltr">${esc(r.phone)}</small></td><td>${esc(r.level?.name||'عضو')}</td><td>${r.level?`${fmt(r.level.value)} ${r.level.metric==='spend'?'ريال':'زيارة'}${r.level.next?`<small>باقي ${fmt(r.level.next.remaining)} إلى ${esc(r.level.next.name)}</small>`:''}`:'—'}</td></tr>`).join('')||'<tr><td colspan="3">لا توجد نتائج.</td></tr>'}</tbody></table></div><div class="eng-pagination"><button class="btn secondary small" data-eng-page="-1" ${page===0?'disabled':''}>السابق</button><span>${fmt(rows.length)} عميل</span><button class="btn secondary small" data-eng-page="1" ${(page+1)*15>=rows.length?'disabled':''}>التالي</button></div></section></div>`;}
function offerRow(o,i){const branches=(shop().branches||[]).filter(b=>b.status==='active');return `<fieldset class="eng-offer" data-offer><legend>عرض ${fmt(i+1)}</legend>${check('enabled','تفعيل العرض',o.enabled)}<div class="eng-grid">${field('اسم العرض',input('name',o.name,'text','required maxlength="40"'))}${field('مضاعفة النقاط',select('multiplier',[[2,'ضعف النقاط'],[3,'ثلاثة أضعاف'],[4,'أربعة أضعاف'],[5,'خمسة أضعاف']],o.multiplier))}${field('من الساعة',input('start',o.start,'time','required'))}${field('حتى الساعة',input('end',o.end,'time','required'))}${field('تاريخ البداية · اختياري',input('from',o.from,'date'))}${field('تاريخ النهاية · اختياري',input('until',o.until,'date'))}</div><div class="field"><span>أيام بداية العرض</span><div class="eng-checkboxes">${days.map((d,n)=>check('day',d,o.days.includes(n),`value="${n}"`)).join('')}</div></div>${branches.length?`<div class="field"><span>الفروع · اتركها فارغة لتطبيقه في جميع فروع البطاقة</span><div class="eng-checkboxes">${branches.map(b=>check('branch',esc(b.name),o.branchIds.includes(b.id),`value="${esc(b.id)}"`)).join('')}</div></div>`:'<p class="eng-note">يطبق على زيارات هذه البطاقة، حتى لو لم تضف فرعًا.</p>'}<button type="button" class="btn secondary small" data-eng-remove="offer">حذف العرض</button></fieldset>`;}
function offers(){if(Loyalty.program(shop().card).type!=='points')return '<section class="panel growth-panel"><h2>زيارات أكثر في الأوقات الهادئة</h2><p>عروض مضاعفة النقاط متاحة للبطاقات التي تعمل بنظام النقاط. اختر بطاقة نقاط أو أنشئ واحدة من «بطاقاتي».</p><p class="eng-note">بطاقات الزيارات والخصم تستمر بقواعدها المعتادة.</p></section>';return `<section class="panel growth-panel"><h2>اجعل وقت الهدوء فرصة للرجوع</h2><p class="sub">حدد الأيام والساعات والفروع، وتضاف النقاط تلقائيًا عند تسجيل الموظف للزيارة.</p><div class="eng-callout">توقيت الرياض. نهاية الوقت غير مشمولة. العرض الذي يتجاوز منتصف الليل ينتمي ليوم بدايته. عند تداخل عروض أو مزايا مستويات، تطبق أعلى مضاعفة فقط.</div><form id="eng-offers"><div id="eng-offers-list">${data.settings.offers.map(offerRow).join('')}</div><button type="button" class="btn secondary" data-eng-add="offer">إضافة عرض</button><p class="eng-note">حتى ستة عروض. الميزة تزيد نقاط الزيارة، وتحفظ سبب الزيادة في سجل العمليات. التراجع يعيد الرصيد السابق كاملًا.</p>${actions()}</form></section>`;}
function reminderRow(r){return `<fieldset class="eng-reminder" data-rule="${r.id}"><legend>${names[r.id]}</legend>${check('enabled','تجهيز تذكيرات هذه الفئة تلقائيًا',r.enabled)}<div class="eng-grid">${r.id==='inactive'?field('بعد انقطاع لمدة · يوم',input('days',r.days,'number','required min="7" max="180"')):input('days',r.days,'hidden')}${field('أقل مدة بين التذكيرات · يوم',input('cooldown',r.cooldown,'number','required min="1" max="90"'))}${field('اسم قالب ميتا · اختياري',input('template',r.template,'text','maxlength="512" dir="ltr" placeholder="reward_ready"'))}${field('لغة القالب',input('language',r.language,'text','required maxlength="10" dir="ltr" placeholder="ar"'))}</div><span class="eng-pill">${fmt(data.reminders.find(x=>x.id===r.id)?.eligible||0)} عميل مؤهل حاليًا</span></fieldset>`;}
function reminders(){return `<div class="eng-callout"><strong>تجهيز التذكيرات متاح — الإرسال متوقف</strong><p>تتجهز مسودة عند تحقق الشرط، وتُلغى إذا زال الاستحقاق أو مرّ أسبوع. الربط الفعلي مع ميتا خطوة لاحقة؛ لا تُرسل رسالة ولا تُحتسب رسالة مرسلة من هذه الشاشة.</p></div><div class="eng-layout"><section class="panel growth-panel"><h2>من تذكّره ومتى؟</h2><form id="eng-reminders">${data.settings.reminders.map(reminderRow).join('')}${actions()}</form></section><section class="panel growth-panel"><div class="eng-heading"><h2>سجل التجهيز</h2><button type="button" class="btn secondary small" data-eng-prepare>تجهيز الآن</button></div><p class="sub">آخر 100 مسودة، بحد 1000 مسودة محفوظة لكل بطاقة. اسم القالب ولغته يُحفظان مع المسودة.</p><div class="eng-draft-list">${data.drafts.map(d=>`<article><div><strong>${esc(d.name)}</strong><small>${names[d.rule]} · ${new Date(d.createdAt).toLocaleString('ar-SA')}</small><small>${d.template?esc(d.template)+' · '+esc(d.language):'لم يحدد قالب'}</small></div><span class="eng-pill ${d.status==='cancelled'?'muted':''}">${d.status==='draft'?'غير مرسلة':'ألغيت'}</span></article>`).join('')||'<p class="eng-empty">لا توجد تذكيرات مجهّزة. فعّل القاعدة ثم احفظها.</p>'}</div></section></div>`;}
const priorOwner=ownerHTML;
ownerHTML=function(){if(view!=='engagement')return priorOwner();const sh=shop();if(!sh)return '';return head('نمو نشاطك','تطوير الولاء','مستويات تكافئ الاستمرار، وعروض تعيد العملاء.','<button class="btn secondary small" data-eng-refresh>تحديث البيانات</button>')+`<nav class="growth-tabs" aria-label="تطوير الولاء">${tabs.map(([id,name])=>`<button class="${tab===id?'active':''}" data-eng-tab="${id}">${name}</button>`).join('')}</nav><div class="growth-toolbar">${field('البطاقة',`<select class="input" data-eng-card>${db.shops.filter(s=>!s.archivedAt).map(s=>`<option value="${esc(s.id)}" ${db.shop===s.id?'selected':''}>${esc(s.card.title||s.name)}</option>`).join('')}</select>`)}</div>${!serverMode?'<section class="panel">تتوفر هذه الأدوات في حساب النشاط الفعلي.</section>':error?`<section class="panel"><p class="error">${esc(error)}</p><button class="btn secondary" data-eng-refresh>إعادة المحاولة</button></section>`:!data||key!==identity()?'<section class="panel" role="status">جارٍ تحميل إعدادات بطاقتك…</section>':tab==='levels'?levels():tab==='offers'?offers():reminders()}`;};
const priorRender=render;
function staffAward(){if(!serverMode||role!=='staff'||lastTx?.type!=='stamp'||lastTx.undone||!lastTx.pointBonus||!lastTx.pointsAdded)return;const text=`أضيفت ${fmt(lastTx.pointsAdded)} نقطة · ${lastTx.pointBonus.offer?.name||'ميزة مستوى '+lastTx.pointBonus.level}`,result=document.querySelector('.scanner-result');if(result&&!result.querySelector('.eng-staff-award'))result.insertAdjacentHTML('beforeend',`<p class="eng-staff-award eng-pill">${esc(text)}</p>`);else if(!result&&stream){const status=document.querySelector('#scan-status');if(status)status.textContent='تم تسجيل العملية. '+text;}}
render=function(){priorRender();staffAward();if(serverMode&&!publicPage&&role==='owner'&&view==='engagement')void refresh();if(serverMode&&!publicPage&&role==='client'&&clientStage==='card'){const m=currentMember(),l=m?.loyaltyLevel,host=document.querySelector('.enroll-issued-panel,.customer-card-panel,.phone-layout');if(l&&host)host.insertAdjacentHTML('beforeend',`<section class="growth-customer-box eng-membership"><span class="eng-pill">${esc(l.name)}</span>${l.benefit?`<p>${esc(l.benefit)}</p>`:''}${l.multiplier>1&&Loyalty.program(shop().card).type==='points'?`<p>ميزة المستوى: ${fmt(l.multiplier)} أضعاف نقاط الزيارة المؤهلة.</p>`:''}${l.next?`<p>باقي ${fmt(l.next.remaining)} ${l.metric==='spend'?'ريال مسجّل':'زيارة'} لمستوى ${esc(l.next.name)}</p><progress max="100" value="${l.percent}" aria-label="تقدم المستوى"></progress>`:'<p>وصلت إلى أعلى مستوى. شكرًا لاستمرارك معنا.</p>'}</section>`);}};
const priorScan=processScan;processScan=async function(code){const old=lastTx;await priorScan(code);if(lastTx!==old)staffAward();};
async function discard(){if(!dirty)return true;if(discardResolve)return false;return new Promise(resolve=>{discardResolve=resolve;modal('تعديلات لم تحفظ','<p>احفظ إعداداتك قبل المغادرة، أو اختر ترك التعديلات.</p>','<button class="btn secondary" type="button" data-eng-stay>العودة للتعديل</button><button class="btn primary" type="button" data-eng-discard>ترك التعديلات</button>');document.querySelector('#modal').addEventListener('close',()=>{const pending=discardResolve;discardResolve=null;pending?.(false);},{once:true});});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-eng-discard],[data-eng-stay]');if(!b)return;e.preventDefault();const pending=discardResolve;discardResolve=null;if(b.hasAttribute('data-eng-discard')){dirty=false;pending?.(true);}else pending?.(false);document.querySelector('#modal').close();});
function changed(){dirty=true;const el=document.querySelector('.eng-save-state');if(el)el.textContent='تعديلات لم تحفظ';}
document.addEventListener('input',e=>{if(e.target.closest('#eng-levels,#eng-offers,#eng-reminders'))changed();});
document.addEventListener('change',async e=>{if(e.target.closest('#eng-levels,#eng-offers,#eng-reminders'))changed();if(!e.target.matches('[data-eng-card]'))return;if(saving||!(await discard())){e.target.value=db.shop;return;}try{const oldRole=role,oldView=view;acceptServer(await api('/api/state?shop='+encodeURIComponent(e.target.value)+(db.scopedBusiness?'&scope='+encodeURIComponent(db.scopedBusiness):'')));role=oldRole;view=oldView;data=null;dirty=false;search='';render();}catch(err){toast(err.message);}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-eng-tab],[data-eng-refresh],[data-eng-add],[data-eng-remove],[data-eng-prepare],[data-eng-page]');if(!b)return;e.preventDefault();if(saving)return toast('انتظر اكتمال الحفظ.');try{
 if(b.dataset.engTab){if(!(await discard()))return;tab=b.dataset.engTab;dirty=false;render();}
 else if(b.hasAttribute('data-eng-refresh')){if(await discard())await refresh(true);}
 else if(b.dataset.engPage){if(!(await discard()))return;page=Math.max(0,page+Number(b.dataset.engPage));dirty=false;render();}
 else if(b.dataset.engAdd){const tier=b.dataset.engAdd==='tier',host=document.querySelector(tier?'#eng-tiers':'#eng-offers-list'),n=host.children.length;if(n>=(tier?3:6))return toast(tier?'حتى ثلاثة مستويات.':'حتى ستة عروض.');host.insertAdjacentHTML('beforeend',tier?levelRow({name:'',threshold:(n+1)*10,multiplier:1,benefit:''},n):offerRow({name:'',enabled:false,multiplier:2,start:'14:00',end:'17:00',days:[0,1,2,3,4],from:'',until:'',branchIds:[]},n));changed();}
 else if(b.dataset.engRemove){const host=b.closest('fieldset');if(b.dataset.engRemove==='tier'&&host.parentElement.children.length===1)return toast('أبقِ مستوى واحدًا على الأقل.');host.remove();changed();}
 else{if(!(await discard()))return;b.disabled=true;data=await api('/api/engagement/prepare',args());dirty=false;render();toast('تم تجهيز '+fmt(data.created)+' مسودة، دون إرسال.');}
 }catch(err){toast(err.message);}finally{b.disabled=false;}
});
// Searching the read-only table must not replace a form with unsaved changes.
document.addEventListener('keydown',async e=>{if(e.target.matches('[data-eng-search]')&&e.key==='Enter'){e.preventDefault();if(saving||!(await discard()))return;search=e.target.value.trim();page=0;dirty=false;render();}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['eng-levels','eng-offers','eng-reminders'].includes(form.id))return;e.preventDefault();e.stopImmediatePropagation();const button=form.querySelector('button[type=submit]');if(button.disabled||saving)return;button.disabled=true;saving=true;try{
 const next=structuredClone(data.settings),v=new FormData(form);
 // Read live controls directly; copying markup would lose edits to input values.
 const values=el=>({get:n=>el.querySelector(`[name="${n}"]`)?.value,has:n=>!!el.querySelector(`[name="${n}"]`)?.checked,all:n=>[...el.querySelectorAll(`[name="${n}"]:checked`)].map(x=>x.value)});
 if(form.id==='eng-levels')next.levels={enabled:v.has('enabled'),metric:v.get('metric'),window:Number(v.get('window')),tiers:[...form.querySelectorAll('[data-tier]')].map(el=>{const f=values(el);return {name:f.get('name'),threshold:Number(f.get('threshold')),multiplier:Number(f.get('multiplier')),benefit:f.get('benefit')};})};
 else if(form.id==='eng-offers')next.offers=[...form.querySelectorAll('[data-offer]')].map(el=>{const f=values(el);return {name:f.get('name'),enabled:f.has('enabled'),multiplier:Number(f.get('multiplier')),start:f.get('start'),end:f.get('end'),from:f.get('from'),until:f.get('until'),days:f.all('day').map(Number),branchIds:f.all('branch')};});
 else next.reminders=[...form.querySelectorAll('[data-rule]')].map(el=>{const f=values(el);return {id:el.dataset.rule,enabled:f.has('enabled'),days:Number(f.get('days')),cooldown:Number(f.get('cooldown')),template:f.get('template'),language:f.get('language')};});
 data=await api('/api/engagement/settings',{...args(),settings:next});dirty=false;render();toast('تم حفظ إعدادات البطاقة.');
 }catch(err){toast(err.message);}finally{button.disabled=false;saving=false;}
},true);
window.addEventListener('beforeunload',e=>{if(dirty&&role==='owner'&&view==='engagement'){e.preventDefault();e.returnValue='';}});
document.addEventListener('click',async e=>{if((!dirty&&!saving)||role!=='owner'||view!=='engagement')return;const b=e.target.closest('[data-action="nav"],[data-action="role"],a[href]');if(!b||b.dataset.view==='engagement')return;e.preventDefault();e.stopImmediatePropagation();if(!saving&&await discard())b.click();},true);
render();
})();
